import numpy as np

def gini(counts):
    p = np.asarray(counts) / sum(counts)
    return 1 - (p ** 2).sum()

def entropy(counts):
    p = np.asarray(counts)
    p = p[p > 0] / p.sum()
    return -(p * np.log2(p)).sum()

# the node from the example: 20 samples, 12/8 -> children 2/6 and 10/2
parent, left, right = (12, 8), (2, 6), (10, 2)

for name, f in [('gini', gini), ('entropy', entropy)]:
    weighted = (sum(left) * f(left) + sum(right) * f(right)) / sum(parent)
    print(f'{name:8s} parent={f(parent):.3f}  children={weighted:.3f}  '
          f'information gain={f(parent) - weighted:.3f}')
